CREATE OR REPLACE FUNCTION public.log_maintenance_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status is distinct from old.status then
    insert into public.maintenance_updates (
      maintenance_request_id,
      actor_id,
      from_status,
      to_status,
      note
    )
    values (
      new.id,
      new.last_updated_by,
      old.status,
      new.status,
      coalesce(new.landlord_response, new.rejected_reason)
    );
  end if;

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.set_maintenance_update_actor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor uuid;
begin
  actor := coalesce(auth.uid(), new.last_updated_by, old.last_updated_by, new.requested_by);

  if actor is null then
    raise exception 'Maintenance update actor is required';
  end if;

  if not public.is_admin(actor)
     and not exists (
       select 1
       from public.tenancies t
       where t.id = new.tenancy_id
         and actor in (t.tenant_id, t.landlord_id)
     ) then
    raise exception 'Maintenance update actor is not a tenancy participant';
  end if;

  new.last_updated_by := actor;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.validate_maintenance_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor uuid;
begin
  actor := coalesce(auth.uid(), new.last_updated_by, new.requested_by);

  if not exists (
    select 1
    from public.tenancies t
    where t.id = new.tenancy_id
      and t.status = 'active'
      and new.requested_by in (t.tenant_id, t.landlord_id)
  ) then
    raise exception 'Maintenance requests require an active tenancy participant';
  end if;

  if actor is null then
    raise exception 'Maintenance actor is required';
  end if;

  new.last_updated_by := actor;
  return new;
end;
$function$
